import inspect
import numpy as np
import mteb

MODEL = "BAAI/bge-small-zh-v1.5"
REVISION = "7999e1d3359715c523056ef9478215996d62a620"
QUERY = "terminal-bench"

model = mteb.get_model(MODEL, revision=REVISION)
docs = [l.rstrip("\n") for l in open("/app/data.txt", encoding="utf-8") if l.strip()]

def encode(texts):
    fn = model.encode
    try:
        params = inspect.signature(fn).parameters
    except (TypeError, ValueError):
        params = {}
    kw = {}
    if "task_name" in params or any(p.kind == p.VAR_KEYWORD for p in params.values()):
        kw["task_name"] = "T2Retrieval"
    try:
        return np.asarray(fn(texts, **kw))
    except (TypeError, KeyError):
        return np.asarray(fn(texts))

emb = encode([QUERY] + docs)
emb = emb / np.linalg.norm(emb, axis=1, keepdims=True)
sims = emb[1:] @ emb[0]
order = np.argsort(-sims)
for r, i in enumerate(order[:6], 1):
    print(r, round(float(sims[i]), 4), docs[i])
result = docs[order[4]]
with open("/app/result.txt", "w", encoding="utf-8") as f:
    f.write(result + "\n")
EOF
